-- Completed package: area52-quest-corrections-batch3-20261021; artifact: 027__rev_20261003_33_coa_uneasy_citizen_objective_marker.sql
-- CoA: 1660018 'Those Who Fell' had no objective marker - only its turn-in pin.
--
-- The quest is finished by casting 256708 'Distilling Spiritual Unrest' (the provided stone 559158)
-- on the Uneasy Citizens (161791) in the Valley of Trials. rev_20260926_35 gave the quest its
-- turn-in marker (quest_poi id 0, ObjectiveIndex -1, at Swa'li 161733, -372 -4123), so a player
-- carrying the open quest saw nothing on the world map for the objective itself.
--
-- The objective is RequiredItemId1 559155 'Spiritual Unrest' x5 - item slot 1, so ObjectiveIndex 4
-- (NPC/object objectives are 0-3, item objectives 4-7; the convention rev_20261001_08 uses for the
-- Cain chain and stock 376/639 carries). The points are the outline of the 15 Uneasy Citizen
-- spawns (creature 161791, map 1), the same way 1660029 outlines its three spawn areas, so the
-- client draws the quest area over the camp in the Valley of Trials.
--
-- Idempotent: delete of the exact keys followed by the insert.

DELETE FROM `quest_poi` WHERE `QuestID` = 1660018 AND `id` = 1;

VALUES (1660018, 1, 4, 1, 4, 0, 0, 1);

DELETE FROM `quest_poi_points` WHERE `QuestID` = 1660018 AND `Idx1` = 1;


-- Completed package: area52-quest-corrections-batch3-20261021; artifact: 028__rev_20261006_01_coa_the_balnirs_rest_objective_markers.sql
-- CoA: 254054 'The Balnirs' Rest' had no objective markers - only its turn-in pin.
--
-- The quest is finished by killing Jorum Balnir 254936, Vara Balnir 254937 and Jarim Balnir 254938 at
-- the graves north of the Chapel of Final Grace, so a player carrying the open quest saw nothing on the
-- world map for any of the three. rev_20260926_14 gave the quest its turn-in marker (quest_poi id 0,
-- ObjectiveIndex -1, at 1911 -153).
--
-- All three objectives are creature objectives (RequiredNpcOrGo1-3 254936-254938, one kill each), so they
-- take ObjectiveIndex 0, 1 and 2 (NPC/object objectives are 0-3, item objectives 4-7; the convention
-- rev_20261001_08 uses for the Cain chain and stock 376 carries). Each of the three is a single spawn
-- (9010601-9010603), so each area is that one point, the same single-point style rev_20261001_08 uses for
-- the Cain family members.
--
-- Idempotent: delete of the exact keys followed by the insert.

DELETE FROM `quest_poi` WHERE (`QuestID`, `id`) IN (
    (254054, 1), (254054, 2), (254054, 3));
DELETE FROM `quest_poi_points` WHERE (`QuestID`, `Idx1`) IN (
    (254054, 1), (254054, 2), (254054, 3));

-- Completed package: area52-quest-corrections-batch3-20261021; artifact: 029__rev_20261006_02_coa_bring_the_end_objective_map.sql
-- CoA: 3341 'Bring the End' drew its objective marker in Tirisfal Glades instead of Razorfen Downs.
--
-- The quest is finished by handing in 10420 'Skull of the Coldbringer' (RequiredItemId1), which only
-- Amnennar the Coldbringer 7358 drops, and his single spawn (guid 87209) is on Razorfen Downs, map 129,
-- at 2403.37 960.93. The objective row carried those right coordinates but MapID 0 and WorldMapAreaId 20,
-- so the client drew the marker in Tirisfal Glades over Balnir Farmstead, where nothing spawns, and the
-- quest could not be completed by following the map.
