-- Completed package: area52-world-quest-batch4-expanded-20261021; artifact: 032__rev_20261006_00_coa_a_humble_duty_objective_markers.sql
-- CoA: 254053 'A Humble Duty' had no objective markers - only its turn-in pin.
--
-- The quest is finished by using six of the seventeen Gravestones 254677 and the single Invincible's
-- Gravestone 254678 in the Chapel of Final Grace graveyard, Tirisfal Glades, so a player carrying the
-- open quest saw nothing on the world map for either objective. rev_20260926_14 gave the quest its
-- turn-in marker (quest_poi id 0, ObjectiveIndex -1, at 1910 -153).
--
-- Both objectives are gameobject objectives (RequiredNpcOrGo1 -254677 x6, RequiredNpcOrGo2 -254678 x1),
-- so they take ObjectiveIndex 0 and 1 (NPC/object objectives are 0-3, item objectives 4-7; the convention
-- rev_20261001_08 uses for the Cain chain and stock 376 carries). The points are DERIVED: the area of the
-- 17 Gravestones is the outline of their spawns, the same way 1660029 outlines its bear, ghoul and zombie
-- spawns and 1660018 its Uneasy Citizens, so the client draws the quest area over the graveyard. The
-- single Invincible's Gravestone is one point.
--
-- Idempotent: delete of the exact keys followed by the insert.

DELETE FROM `quest_poi` WHERE (`QuestID`, `id`) IN (
    (254053, 1), (254053, 2));
DELETE FROM `quest_poi_points` WHERE (`QuestID`, `Idx1`) IN (
    (254053, 1), (254053, 2));

-- Completed package: area52-world-quest-batch4-expanded-20261021; artifact: 033__rev_20261006_30_coa_a_humble_duty_gravestone_cooldown.sql
-- A Humble Duty: upstream c683075584, qualified against the Area 52 goober reader.
-- Add a shared 30-second reuse cooldown to each grave and keep it from despawning after use.
-- This prevents rapid repeat clicks; it does not permanently track which graves each player used.
-- GameObject::Use checks GO_FLAG_IN_USE before credit and sets it when autoCloseTime is nonzero.
-- The timer clears the flag after 30000 milliseconds. Data5=0 preserves the static grave afterward.
UPDATE `gameobject_template` SET `Data3` = 30000, `Data5` = 0
WHERE `entry` IN (254677, 254678);

-- Completed package: area52-world-quest-batch4-expanded-20261021; artifact: 034__rev_20261017_12_silithid_protector_hostile_faction.sql
-- Egg Hunt (quest 868): the Silithid Protectors (3503) around the Silithid Mounds
-- show Neutral instead of Hostile. The template carries faction template 7,
-- whose masks are all zero (no hostility to players, no enemy factions), while
-- every other silithid at the same site (Creeper 3250, Grub 3251, Swarmer 3252)
-- uses faction template 413: hostile to players and an enemy of faction 309
-- "Scorpid". Stock data shipped the 7, so this is a data correction, not a
-- regression restore. No spawn script, C++ script, summon group, pool, event or
-- template/script override touches 3503 or the mound (3685), so the template
-- faction governs every spawn. Align the Protector with its neighbours.

UPDATE `creature_template` SET `faction` = 413 WHERE `entry` = 3503;

